/*
α = 1 + μ/λ - μ/(4λ)
J =`$f_0$`⋅(`$f_1$`×`$f_2$`)
`$P(F)$` = μ(1-1/(`$I_C$`+1))F + λ(J- α)`$\frac{\partial J}{\partial F}$`

where 
F: ℝ^(3×3): the deformation gradient
μ: ℝ : the Lamé constant
`$I_C$`: ℝ : the first right Cauchy-Green invariant
λ: ℝ : the Lamé constant

`$\frac{\partial J}{\partial F}$` = [`$f_1$`×`$f_2$` `$f_2$`×`$f_0$` `$f_0$`×`$f_1$`]

where 
`$f_0$`: ℝ^3: the first column of matrix F 
`$f_1$`: ℝ^3: the second column of matrix F
`$f_2$`: ℝ^3: the third column of matrix F


*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT α;
    DT J;
    Eigen::Matrix<DT, 3, 3> PF;
    Eigen::Matrix<DT, 3, 3> fracpartialJpartialF;

    heartlib(
        const Eigen::Matrix<double, 3, 3> & F,
        const double & μ,
        const double & I_C,
        const double & λ,
        const Eigen::Matrix<double, 3, 1> & f_0,
        const Eigen::Matrix<double, 3, 1> & f_1,
        const Eigen::Matrix<double, 3, 1> & f_2)
    {

        // α = 1 + μ/λ - μ/(4λ)
        α = 1 + μ / DT(λ) - μ / DT((4 * λ));
        // J =`$f_0$`⋅(`$f_1$`×`$f_2$`)
        J = (f_0).dot(((f_1).cross(f_2)));
        // `$\frac{\partial J}{\partial F}$` = [`$f_1$`×`$f_2$` `$f_2$`×`$f_0$` `$f_0$`×`$f_1$`]
        Eigen::Matrix<DT, 3, 3> fracpartialJpartialF_0;
        fracpartialJpartialF_0 << (f_1).cross(f_2), (f_2).cross(f_0), (f_0).cross(f_1);
        fracpartialJpartialF = fracpartialJpartialF_0;
        // `$P(F)$` = μ(1-1/(`$I_C$`+1))F + λ(J- α)`$\frac{\partial J}{\partial F}$`
        PF = μ * (1 - 1 / DT((I_C + 1))) * F + λ * (J - α) * fracpartialJpartialF;
    }
};

